public class CircleGemHelper {
	public static final String ITEM_GEM_NBT_TAG = "Gem";

	/**
	 * Returns true if gems are applicable to the item
	 * @param item
	 * @return
	 */
	public static boolean isApplicable(Item item) {
		return (item instanceof ItemAmulet || item instanceof ItemArmor || item instanceof ItemSword || item instanceof ItemBow || item instanceof ItemTool || item instanceof ItemShield) && item instanceof ItemAmphibiousArmor == false;
	}

	/**
	 * Returns true if gems are applicable to the entity
	 * @param entity
	 * @return
	 */
	public static boolean isApplicable(Entity entity) {
		return entity instanceof EntityLivingBase;
	}

	/**
	 * Sets the gem of the specified item stack
	 * @param stack
	 * @param gem
	 */
	public static void setGem(ItemStack stack, CircleGemType gem) {
		NBTTagCompound nbt = NBTHelper.getStackNBTSafe(stack);
		nbt.setInteger(ITEM_GEM_NBT_TAG, gem.id);
	}

	/**
	 * Returns the gem on the specified item stack
	 * @param stack
	 * @return
	 */
	public static CircleGemType getGem(ItemStack stack) {
		NBTTagCompound nbt = stack.getTagCompound();
		if(nbt != null && nbt.hasKey(ITEM_GEM_NBT_TAG, Constants.NBT.TAG_INT)) {
			return CircleGemType.fromID(nbt.getInteger(ITEM_GEM_NBT_TAG));
		}
		return CircleGemType.NONE;
	}

	/**
	 * Adds a gem to the specified entity
	 * @param entity

	 */
	public static void addGem(Entity entity, CircleGemType gemType, CircleGem.CombatType combatType) {
		ICircleGemCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_ENTITY_CIRCLE_GEM, null);
		if(cap != null) {
			CircleGem gem = new CircleGem(gemType, combatType);
			if(cap.canAdd(gem)) {
				cap.addGem(gem);
			}
		}
	}

	/**
	 * Returns a list of gems on the specified entity
	 * @param entity
	 * @return
	 */
	public static List<CircleGem> getGems(Entity entity) {
		List<CircleGem> gems = new ArrayList<CircleGem>();
		ICircleGemCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_ENTITY_CIRCLE_GEM, null);
		if(cap != null) {
			return cap.getGems();
		}
		return gems;
	}

	/**
	 * Returns the gem of the slot on the specified entity
	 * @param entity
	 * @param slot
	 * @return
	 */
	public static CircleGem getGem(Entity entity, int slot) {
		ICircleGemCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_ENTITY_CIRCLE_GEM, null);
		if(cap != null) {
			List<CircleGem> gems = cap.getGems();
			if(gems.size() > slot)
				return cap.getGems().get(slot);
		}
		return new CircleGem(CircleGemType.NONE, CombatType.BOTH);
	}

	/**
	 * Adds the gem property overrides to the specified item
	 * @param item
	 */
	public static void addGemPropertyOverrides(Item item) {
		item.addPropertyOverride(new ResourceLocation("gem"), (stack, worldIn, entityIn) -> CircleGemHelper.getGem(stack).id);
	}

	public static final float MAX_GEM_DAMAGE_VARIATION = 8.0F;
	public static final float GEM_PROC_CHANCE = 0.15F;

	/**
	 * Handles an attack and returns the new damage
	 * @param damageSource
	 * @param attackedEntity
	 * @param damage
	 * @return
	 */
	public static float handleAttack(DamageSource damageSource, EntityLivingBase attackedEntity, float damage) {
		if(attackedEntity.hurtTime == 0 && attackedEntity.deathTime == 0 && damageSource instanceof EntityDamageSource && (attackedEntity instanceof EntityPlayer == false || !((EntityPlayer)attackedEntity).capabilities.disableDamage)) {
			Entity attacker;
			Entity source;
			if(damageSource instanceof EntityDamageSourceIndirect) {
				attacker = damageSource.getTrueSource();
				source = damageSource.getImmediateSource();
			} else {
				attacker = damageSource.getImmediateSource();
				source = attacker;
			}
			if(attacker != null && source != null) {
				List<CircleGem> attackerGems = CircleGemHelper.getGems(attacker);
				List<CircleGem> sourceGems = new ArrayList<CircleGem>();
				if(source != attacker) {
					sourceGems.addAll(CircleGemHelper.getGems(source));
				}
				CircleGemType attackerItemGem = CircleGemType.NONE;
				if(attacker instanceof EntityLivingBase) {
					ItemStack heldItem = getActiveItem(attacker);
					if(!heldItem.isEmpty()) attackerItemGem = CircleGemHelper.getGem(heldItem);
				}
				//At this point either userGem or attackerItemGem are set because either there's a user shooting a (non-living) projectile (user != attacker) or the user is attacking directly (user == attacker)
				List<CircleGem> attackedGems = CircleGemHelper.getGems(attackedEntity); 
				CircleGemType attackedBlockingItemGem = CircleGemType.NONE;
				if(attackedEntity instanceof EntityPlayer) {
					EntityPlayer player = (EntityPlayer) attackedEntity;
					ItemStack heldItem = player.getActiveItemStack();
					if(!heldItem.isEmpty() && player.isActiveItemStackBlocking()) {
						attackedBlockingItemGem = CircleGemHelper.getGem(heldItem);
					}
				}
				int gemRelation = 0;
				for(CircleGem gem : attackerGems) {
					if(gem.matchCombatType(CircleGem.CombatType.OFFENSIVE)) {
						for(CircleGem gemAttacked : attackedGems) {
							if(gemAttacked.matchCombatType(CircleGem.CombatType.DEFENSIVE)) {
								gemRelation += gem.getGemType().getRelation(gemAttacked.getGemType());
							}
						}
						gemRelation += gem.getGemType().getRelation(attackedBlockingItemGem);
					}
				}
				for(CircleGem gemAttacked : attackedGems) {
					if(gemAttacked.matchCombatType(CircleGem.CombatType.DEFENSIVE)) {
						gemRelation += attackerItemGem.getRelation(gemAttacked.getGemType());
					}
				}
				gemRelation += attackerItemGem.getRelation(attackedBlockingItemGem);
				for(CircleGem gem : sourceGems) {
					if(gem.matchCombatType(CircleGem.CombatType.OFFENSIVE)) {
						for(CircleGem gemAttacked : attackedGems) {
							if(gemAttacked.matchCombatType(CircleGem.CombatType.DEFENSIVE)) {
								gemRelation += gem.getGemType().getRelation(gemAttacked.getGemType());
							}
						}
						gemRelation += gem.getGemType().getRelation(attackedBlockingItemGem);
					}
				}
				Iterable<ItemStack> equipment = attackedEntity.getEquipmentAndArmor();
				for(ItemStack equipmentStack : equipment) {
					if(!equipmentStack.isEmpty() && !equipmentStack.equals(getActiveItem(attackedEntity)) && equipmentStack.getItem() instanceof ItemArmor) {
						CircleGemType armorGem = CircleGemHelper.getGem(equipmentStack);
						for(CircleGem gem : attackerGems) {
							if(gem.matchCombatType(CombatType.OFFENSIVE)) {
								gemRelation += gem.getGemType().getRelation(armorGem);
							}
						}
						gemRelation += attackerItemGem.getRelation(armorGem);
						for(CircleGem gem : sourceGems) {
							if(gem.matchCombatType(CombatType.OFFENSIVE)) {
								gemRelation += gem.getGemType().getRelation(armorGem);
							}
						}
					}
				}
				float gemDamageVariation = Math.min(((gemRelation != 0 ? Math.signum(gemRelation) * 1 : 0) + gemRelation) / 6.0F * MAX_GEM_DAMAGE_VARIATION, MAX_GEM_DAMAGE_VARIATION);
				if(gemDamageVariation != 0.0F) {
					damage = Math.max(damage + gemDamageVariation, 1.0F);
				}
				damage = Math.max(0, damage);

				boolean attackerProc = attacker.world.rand.nextFloat() <= (source == attacker && !attacker.onGround && attacker.motionY < 0 ? GEM_PROC_CHANCE * 1.33F : GEM_PROC_CHANCE);
				boolean defenderProc = attacker.world.rand.nextFloat() <= GEM_PROC_CHANCE;

				boolean attackerProcd = false;
				boolean defenderProcd = false;

				List<CircleGemType> attackerProcdGems = new ArrayList<CircleGemType>();
				List<CircleGemType> defenderProcdGems = new ArrayList<CircleGemType>();

				//Attacker gems
				TObjectIntHashMap<CircleGemType> attackerGemCounts = new TObjectIntHashMap<CircleGemType>();
				for(CircleGem gem : attackerGems) {
					if(gem.matchCombatType(CircleGem.CombatType.OFFENSIVE)) {
						attackerGemCounts.adjustOrPutValue(gem.getGemType(), 1, 1);
					}
				}
				for(CircleGem gem : sourceGems) {
					if(gem.matchCombatType(CircleGem.CombatType.OFFENSIVE)) {
						attackerGemCounts.adjustOrPutValue(gem.getGemType(), 1, 1);
					}
				}
				attackerGemCounts.adjustOrPutValue(attackerItemGem, 1, 1);
				for(CircleGemType gem : attackerGemCounts.keySet()) {
					if(gem != CircleGemType.NONE && applyProc(gem, attacker, source, attacker, attackedEntity, attackerProc, defenderProc, getMultipleProcStrength(attackerGemCounts.get(gem), damage), damageSource, damage)) {
						attackerProcd = true;
						if(!attackerProcdGems.contains(gem)){
							attackerProcdGems.add(gem);
						}
					}
				}

				//Defender gems
				TObjectIntHashMap<CircleGemType> defenderGemCounts = new TObjectIntHashMap<CircleGemType>();
				for(ItemStack equipmentStack : equipment) {
					if(!equipmentStack.isEmpty() && !equipmentStack.equals(getActiveItem(attackedEntity)) && equipmentStack.getItem() instanceof ItemArmor) {
						CircleGemType armorGem = CircleGemHelper.getGem(equipmentStack);
						if(armorGem != CircleGemType.NONE) {
							defenderGemCounts.adjustOrPutValue(armorGem, 1, 1);
						}
					}
				}
				for(CircleGem gem : attackedGems) {
					if(gem.matchCombatType(CircleGem.CombatType.DEFENSIVE)) {
						defenderGemCounts.adjustOrPutValue(gem.getGemType(), 1, 1);
					}
				}
				defenderGemCounts.adjustOrPutValue(attackedBlockingItemGem, 1, 1);
				for(CircleGemType gem : defenderGemCounts.keySet()) {
					if(gem != CircleGemType.NONE && applyProc(gem, attackedEntity, source, attacker, attackedEntity, attackerProc, defenderProc, getMultipleProcStrength(defenderGemCounts.get(gem), damage), damageSource, damage)) {
						defenderProcd = true;
						if(!defenderProcdGems.contains(gem)){
							defenderProcdGems.add(gem);
						}
					}
				}

				if(attackerProcd || defenderProcd) {
					World world = attackedEntity.world;
					int dim = 0;
					if (world instanceof WorldServer) {
						dim = ((WorldServer)world).provider.getDimension();
					}
					if(attackerProcd) {
						for(CircleGemType gem : attackerProcdGems) {
							TheBetweenlands.networkWrapper.sendToAllAround(new MessageGemProc(attackedEntity, true, gem), new TargetPoint(dim, attackedEntity.posX, attackedEntity.posY, attackedEntity.posZ, 64.0D));
						}
					}
					if(defenderProcd) {
						for(CircleGemType gem : defenderProcdGems) {
							TheBetweenlands.networkWrapper.sendToAllAround(new MessageGemProc(attackedEntity, false, gem), new TargetPoint(dim, attackedEntity.posX, attackedEntity.posY, attackedEntity.posZ, 64.0D));
						}
					}
					source.world.playSound(null, source.posX, source.posY, source.posZ, SoundEvents.ENTITY_ARROW_HIT_PLAYER, SoundCategory.PLAYERS, 1, 1);
					source.world.playSound(null, attackedEntity.posX, attackedEntity.posY, attackedEntity.posZ, SoundEvents.ENTITY_ARROW_HIT_PLAYER, SoundCategory.PLAYERS, 1, 1);
				}
			}
		}
		return damage;
	}

	private static ItemStack getActiveItem(Entity entity) {
		if(entity instanceof EntityLivingBase) {
			EntityLivingBase living = (EntityLivingBase) entity;
			if(!living.getActiveItemStack().isEmpty()) {
				return living.getActiveItemStack();
			}
			if(living.getActiveHand() != null) {
				return living.getHeldItem(living.getActiveHand());
			}
		}
		return ItemStack.EMPTY;
	}

	private static float getMultipleProcStrength(int procs, float strength) {
		float ret = 0;
		for(int i = 0; i < procs; i++) {
			ret += strength / Math.pow(1.4F, i);
		}
		return ret;
	}

	private static boolean applyProc(CircleGemType gem, Entity owner, Entity source, Entity attacker, Entity defender, boolean attackerProc, boolean defenderProc, float strength, DamageSource damageSource, float damage) {
		boolean isAttacker = owner == attacker;
		if((isAttacker && attackerProc) || (!isAttacker && defenderProc)) {
			return gem.applyProc(isAttacker, owner, source, attacker, defender, strength, damageSource, damage);
		}
		return false;
	}
}

package thebetweenlands.common.capability.circlegem;

import java.util.function.Consumer;

import javax.annotation.Nullable;

import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.init.MobEffects;
import net.minecraft.item.ItemStack;
import net.minecraft.potion.PotionEffect;
import net.minecraft.util.DamageSource;
import net.minecraft.util.math.MathHelper;
import thebetweenlands.api.item.IAmphibiousArmorUpgrade;
import thebetweenlands.common.item.armor.amphibious.AmphibiousArmorUpgrades;
import thebetweenlands.common.item.armor.amphibious.ItemAmphibiousArmor;
import thebetweenlands.common.item.misc.ItemGemSinger;

public enum CircleGemType {
	AQUA("aqua", 1, ItemGemSinger.GemSingerTarget.AQUA_MIDDLE_GEM),
	CRIMSON("crimson", 2, ItemGemSinger.GemSingerTarget.CRIMSON_MIDDLE_GEM),
	GREEN("green", 3, ItemGemSinger.GemSingerTarget.GREEN_MIDDLE_GEM),
	NONE("none", 0, null);

	public final String name;
	public final int id;

	@Nullable
	public final ItemGemSinger.GemSingerTarget gemSingerTarget;

	public static final CircleGemType[] TYPES = CircleGemType.values();

	private CircleGemType(String name, int id, ItemGemSinger.GemSingerTarget gemSingerTarget) {
		this.name = name;
		this.id = id;
		this.gemSingerTarget = gemSingerTarget;
	}

	/**
	 * Returns the relation between two gems.
	 * <p>0: Neutral
	 * <p>1: This gem has an advantage over the other gem
	 * <p>-1: This gem has a disadvantage over the other gem
	 * @param gem Circle gem to compare to
	 * @return
	 */
	public int getRelation(CircleGemType gem) {
		switch(this) {
		case CRIMSON:
			switch(gem){
			case GREEN:
				return 1;
			case AQUA:
				return -1;
			default:
				return 0;
			}
		case GREEN:
			switch(gem){
			case AQUA:
				return 1;
			case CRIMSON:
				return -1;
			default:
				return 0;
			}
		case AQUA:
			switch(gem){
			case CRIMSON:
				return 1;
			case GREEN:
				return -1;
			default:
				return 0;
			}
		default:
			return 0;
		}
	}

	/**
	 * Applies the gem proc to the attacker or defender
	 * @param isAttacker Whether the owner is the attacker
	 * @param owner Owner of the gem
	 * @param source The source (damage source, e.g. the entity that shot the projectile)
	 * @param attacker The entity that is actually attacking (can be both the owner himself or a projectile)
	 * @param defender The defending entity
	 * @param strength Proc strength
	 * @param damageSource The damage source
	 * @param damage The damage that was dealt
	 */
	public boolean applyProc(boolean isAttacker, Entity owner, Entity source, Entity attacker, Entity defender, float strength, DamageSource damageSource, float damage) {
		switch(this) {
		case CRIMSON:
			if(isAttacker) {
				if(defender instanceof EntityLivingBase) {
					float knockbackStrength = Math.min(2.5F / 10.0F * (float)strength, 2.5F);
					((EntityLivingBase)defender).knockBack(attacker, knockbackStrength, attacker.posX - defender.posX, attacker.posZ - defender.posZ);
					if(attacker instanceof EntityLivingBase) {
						((EntityLivingBase)attacker).addPotionEffect(new PotionEffect(MobEffects.STRENGTH, 110, Math.min(MathHelper.floor(strength * 0.2F), 2)));
					}
					if(source != attacker && source instanceof EntityLivingBase) {
						((EntityLivingBase)source).addPotionEffect(new PotionEffect(MobEffects.STRENGTH, 110, Math.min(MathHelper.floor(strength * 0.2F), 2)));
					}
					return true;
				}
			} else {
				DamageSource returnedDamageSource;
				if(defender instanceof EntityPlayer) {
					returnedDamageSource = DamageSource.causePlayerDamage((EntityPlayer)defender);
				} else if(defender instanceof EntityLivingBase) {
					returnedDamageSource = DamageSource.causeMobDamage((EntityLivingBase)defender);
				} else {
					returnedDamageSource = DamageSource.GENERIC;
				}
				attacker.attackEntityFrom(returnedDamageSource, Math.min(damage / 16.0F * strength, damage / 1.5F));
				if(source != attacker) {
					source.attackEntityFrom(returnedDamageSource, Math.min(damage / 16.0F * strength, damage / 1.5F));
				}
				return true;
			}
			break;
		case GREEN:
			if(isAttacker) {
				boolean healed = false;
				if(attacker instanceof EntityLivingBase) {
					((EntityLivingBase)attacker).heal(Math.min(Math.max(strength * 0.45F, 1.0F), 10.0F));
					healed = true;
				}
				if(source != attacker && source instanceof EntityLivingBase) {
					((EntityLivingBase)source).heal(Math.min(Math.max(strength * 0.45F, 1.0F), 10.0F));
					healed = true;
				}
				return healed;
			} else {
				if(defender instanceof EntityLivingBase) {
					((EntityLivingBase)defender).addPotionEffect(new PotionEffect(MobEffects.ABSORPTION, 260, Math.min(MathHelper.floor(strength * 0.25F), 2)));
					return true;
				}
			}
			break;
		case AQUA:
			if(isAttacker) {
				if(defender instanceof EntityLivingBase) {
					int amplifier = Math.min(MathHelper.floor(strength * 0.1F), 2);
					switch(amplifier) {
					case 0:
						((EntityLivingBase)defender).addPotionEffect(new PotionEffect(MobEffects.WEAKNESS, 80, 0));
						break;
					case 1:
					case 2:
						((EntityLivingBase)defender).addPotionEffect(new PotionEffect(MobEffects.WEAKNESS, 40, amplifier));
						break;
					}
					return true;
				}
				break;
			} else {
				if(defender instanceof EntityLivingBase) {
					((EntityLivingBase)defender).addPotionEffect(new PotionEffect(MobEffects.RESISTANCE, 130, Math.min(MathHelper.floor(strength * 0.3F), 2)));
					return true;
				}
			}
			break;
		default:
		}
		return false;
	}

	/**
	 * Returns the gem for the specified name
	 * @param name
	 * @return
	 */
	public static CircleGemType fromName(String name) {
		for(CircleGemType gem : TYPES) {
			if(gem.name.equals(name)) {
				return gem;
			}
		}
		return NONE;
	}

	/**
	 * Returns the gem for the specified ID
	 * @param id
	 * @return
	 */
	public static CircleGemType fromID(int id) {
		for(CircleGemType gem : TYPES) {
			if(gem.id == id) {
				return gem;
			}
		}
		return NONE;
	}

	public final IAmphibiousArmorUpgrade getAmphibiousArmorUpgrade() {
		switch(this) {
		case AQUA:
			return AmphibiousArmorUpgrades.AQUA_GEM;
		case GREEN:
			return AmphibiousArmorUpgrades.GREEN_GEM;
		case CRIMSON:
			return AmphibiousArmorUpgrades.CRIMSON_GEM;
		}
		return null;
	}

	public final Consumer<ItemStack> getAmphibiousArmorOnChangedHandler() {
		return armor -> {
			if(armor.getItem() instanceof ItemAmphibiousArmor) {
				if(((ItemAmphibiousArmor) armor.getItem()).getUpgradeCount(armor, this.getAmphibiousArmorUpgrade()) > 0) {
					CircleGemHelper.setGem(armor, this);
				} else {
					CircleGemHelper.setGem(armor, CircleGemType.NONE);
				}
			}
		};
	}
}

package thebetweenlands.common.capability.equipment;

import javax.annotation.Nullable;

import com.google.common.collect.ImmutableList;

import net.minecraft.inventory.IInventory;

public enum EnumEquipmentInventory {
	MISC(3, 32), AMULET(1, 3), RING(2, 2);

	public static final ImmutableList<EnumEquipmentInventory> VALUES = ImmutableList.copyOf(EnumEquipmentInventory.values());

	/**
	 * The ID of this inventory
	 */
	public final int id;

	/**
	 * The maximum stack size (check {@link IInventory#getSizeInventory()} for the actual size!)
	 */
	public final int maxSize;

	private EnumEquipmentInventory(int id, int maxSize) {
		this.id = id;
		this.maxSize = maxSize;
	}

	@Nullable
	public static EnumEquipmentInventory fromID(int id) {
		for(EnumEquipmentInventory inv : EnumEquipmentInventory.VALUES) {
			if(inv.id == id) {
				return inv;
			}
		}
		return null;
	}
}

package thebetweenlands.common.capability.equipment;

import java.util.EnumMap;
import java.util.Map;

import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.inventory.IInventory;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.NonNullList;
import net.minecraft.util.ResourceLocation;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.util.Constants;
import thebetweenlands.api.capability.IEquipmentCapability;
import thebetweenlands.api.capability.ISerializableCapability;
import thebetweenlands.common.capability.base.EntityCapability;
import thebetweenlands.common.inventory.InventoryEquipment;
import thebetweenlands.common.inventory.InventoryEquipmentAmulets;
import thebetweenlands.common.lib.ModInfo;
import thebetweenlands.common.registries.CapabilityRegistry;

public class EquipmentEntityCapability extends EntityCapability<EquipmentEntityCapability, IEquipmentCapability, EntityPlayer> implements IEquipmentCapability, ISerializableCapability {
	private Map<EnumEquipmentInventory, NonNullList<ItemStack>> allInventoryStacks = new EnumMap<>(EnumEquipmentInventory.class);
	private Map<EnumEquipmentInventory, IInventory> inventories = new EnumMap<>(EnumEquipmentInventory.class);
	private int amuletSlots = 1;

	public EquipmentEntityCapability() {
		for (EnumEquipmentInventory inventory : EnumEquipmentInventory.VALUES) {
			this.allInventoryStacks.put(inventory, NonNullList.withSize(inventory.maxSize, ItemStack.EMPTY));
		}
	}

	@Override
	public ResourceLocation getID() {
		return new ResourceLocation(ModInfo.ID, "equipment");
	}

	@Override
	protected Capability<IEquipmentCapability> getCapability() {
		return CapabilityRegistry.CAPABILITY_EQUIPMENT;
	}

	@Override
	protected Class<IEquipmentCapability> getCapabilityClass() {
		return IEquipmentCapability.class;
	}

	@Override
	protected EquipmentEntityCapability getDefaultCapabilityImplementation() {
		return new EquipmentEntityCapability();
	}

	@Override
	public boolean isApplicable(Entity entity) {
		return entity instanceof EntityLivingBase;
	}

	@Override
	public boolean isPersistent(EntityPlayer oldPlayer, EntityPlayer newPlayer, boolean wasDead) {
		return !wasDead || this.getEntity().world.getGameRules().getBoolean("keepInventory");
	}

	@Override
	public IInventory getInventory(EnumEquipmentInventory inventoryType) {
		IInventory inventory = this.inventories.get(inventoryType);
		if(inventory == null) {
			switch (inventoryType) {
			case AMULET:
				inventory = new InventoryEquipmentAmulets(this, this.allInventoryStacks.get(inventoryType));
				break;
			default:
				inventory = new InventoryEquipment(this, this.allInventoryStacks.get(inventoryType));
				break;
			}
			this.inventories.put(inventoryType, inventory);
		}
		return inventory;
	}

	@Override
	public void writeToNBT(NBTTagCompound nbt) {
		nbt.setInteger("amuletSlots", this.amuletSlots);
		NBTTagList inventoryList = new NBTTagList();
		for (EnumEquipmentInventory inventoryType : EnumEquipmentInventory.VALUES) {
			NonNullList<ItemStack> inventoryStacks = this.allInventoryStacks.get(inventoryType);
			NBTTagCompound inventoryNbt = new NBTTagCompound();
			NBTTagList slotList = new NBTTagList();
			for (int c = 0; c < inventoryStacks.size(); c++) {
				ItemStack stack = inventoryStacks.get(c);
				if (!stack.isEmpty()) {
					NBTTagCompound slotNbt = new NBTTagCompound();
					slotNbt.setInteger("slot", c);
					slotNbt.setTag("stack", stack.writeToNBT(new NBTTagCompound()));
					slotList.appendTag(slotNbt);
				}
			}
			if (slotList.tagCount() > 0) {
				inventoryNbt.setInteger("id", inventoryType.id);
				inventoryNbt.setTag("items", slotList);
				inventoryList.appendTag(inventoryNbt);
			}
		}
		if (inventoryList.tagCount() > 0)
			nbt.setTag("inventories", inventoryList);
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		this.inventories.clear();
		for (EnumEquipmentInventory inventory : EnumEquipmentInventory.VALUES) {
			this.allInventoryStacks.put(inventory, NonNullList.withSize(inventory.maxSize, ItemStack.EMPTY));
		}
		if (nbt.hasKey("amuletSlots")) {
			this.amuletSlots = nbt.getInteger("amuletSlots");
		}
		if (nbt.hasKey("inventories")) {
			NBTTagList inventoryList = nbt.getTagList("inventories", Constants.NBT.TAG_COMPOUND);
			for (int i = 0; i < inventoryList.tagCount(); i++) {
				NBTTagCompound inventoryNbt = inventoryList.getCompoundTagAt(i);
				if (inventoryNbt.hasKey("items")) {
					int id = inventoryNbt.getInteger("id");
					EnumEquipmentInventory inventoryType = EnumEquipmentInventory.fromID(id);
					if (inventoryType != null) {
						NonNullList<ItemStack> inventoryStacks = this.allInventoryStacks.get(inventoryType);
						NBTTagList slotList = inventoryNbt.getTagList("items", Constants.NBT.TAG_COMPOUND);
						for (int c = 0; c < slotList.tagCount(); c++) {
							NBTTagCompound slotNbt = slotList.getCompoundTagAt(c);
							int slot = slotNbt.getInteger("slot");
							if (slot < inventoryStacks.size()) {
								inventoryStacks.set(slot, new ItemStack(slotNbt.getCompoundTag("stack")));
							}
						}
					}
				}
			}
		}
	}

	@Override
	public void writeTrackingDataToNBT(NBTTagCompound nbt) {
		this.writeToNBT(nbt);
	}

	@Override
	public void readTrackingDataFromNBT(NBTTagCompound nbt) {
		this.readFromNBT(nbt);
	}

	@Override
	public int getTrackingTime() {
		return 10;
	}

	@Override
	public int getAmuletSlots() {
		return this.amuletSlots;
	}

	@Override
	public void setAmuletSlots(int slots) {
		this.amuletSlots = slots;
	}
}

package thebetweenlands.common.capability.equipment;

import javax.annotation.Nullable;

import net.minecraft.entity.Entity;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.inventory.IInventory;
import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import net.minecraftforge.items.IItemHandler;
import net.minecraftforge.items.ItemHandlerHelper;
import net.minecraftforge.items.wrapper.InvWrapper;
import thebetweenlands.api.capability.IEquipmentCapability;
import thebetweenlands.api.item.IEquippable;
import thebetweenlands.common.registries.AdvancementCriterionRegistry;
import thebetweenlands.common.registries.CapabilityRegistry;

public class EquipmentHelper {
	/**
	 * NBT containing whether the entity does *not* have any equipment.
	 * Using the inverse because old entities may not have this tag yet and so we can still do a quick check
	 * instead of having to do hasKey.
	 */
	public static final String NBT_HAS_NO_EQUIPMENT = "thebetweenlands.has_no_equipment";

	/**
	 * Returns the first item stack of the specified item, or empty if none is found
	 * @param entity
	 * @param item
	 * @return
	 */
	public static ItemStack getEquipment(EnumEquipmentInventory inventory, Entity entity, Item item) {
		IEquipmentCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_EQUIPMENT, null);
		if(cap != null) {
			IInventory mainInv = cap.getInventory(inventory);
			for(int i = 0; i < mainInv.getSizeInventory(); i++) {
				ItemStack stack = mainInv.getStackInSlot(i);
				if(!stack.isEmpty() && stack.getItem() == item) {
					return stack;
				}
			}
		}

		return ItemStack.EMPTY;
	}

	/**
	 * Tries to equip the specified item, returns the leftover stack
	 * @param player
	 * @param target
	 * @param stack
	 * @return
	 */
	public static ItemStack equipItem(@Nullable EntityPlayer player, Entity target, ItemStack stack, boolean simulate) {
		if(stack.getItem() instanceof IEquippable) {
			IEquipmentCapability cap = target.getCapability(CapabilityRegistry.CAPABILITY_EQUIPMENT, null);
			if(cap != null) {
				IEquippable equippable = (IEquippable) stack.getItem();

				if(equippable.canEquip(stack, player, target)) {
					EnumEquipmentInventory type = equippable.getEquipmentCategory(stack);

					stack = stack.copy();

					if (target instanceof EntityPlayerMP) {
						AdvancementCriterionRegistry.EQUIP.trigger((EntityPlayerMP) target, stack);
					}

					IInventory inv = cap.getInventory(type);
					IItemHandler wrapper = new InvWrapper(inv);

					ItemStack result = ItemHandlerHelper.insertItem(wrapper, stack, true);

					if(simulate) {
						return result;
					}

					if(result.isEmpty() || result.getCount() != stack.getCount()) {
						target.getEntityData().setBoolean(NBT_HAS_NO_EQUIPMENT, false);

						equippable.onEquip(stack, target, inv);

						return ItemHandlerHelper.insertItem(wrapper, stack, false);
					}
				}
			}
		}

		return stack;
	}

	/**
	 * Tries to equip the specified item in the specified slot, returns the leftover stack
	 * @param player
	 * @param target
	 * @param stack
	 * @param slot
	 * @param simulate
	 * @return
	 */
	public static ItemStack equipItem(@Nullable EntityPlayer player, Entity target, ItemStack stack, int slot, boolean simulate) {
		if(slot >= 0 && stack.getItem() instanceof IEquippable) {
			IEquipmentCapability cap = target.getCapability(CapabilityRegistry.CAPABILITY_EQUIPMENT, null);
			if(cap != null) {
				IEquippable equippable = (IEquippable) stack.getItem();

				if(equippable.canEquip(stack, player, target)) {
					EnumEquipmentInventory type = equippable.getEquipmentCategory(stack);

					IInventory inv = cap.getInventory(type);
					if(slot < inv.getSizeInventory()) {
						IItemHandler wrapper = new InvWrapper(inv);

						stack = stack.copy();

						if (target instanceof EntityPlayerMP) {
							AdvancementCriterionRegistry.EQUIP.trigger((EntityPlayerMP) target, stack);
						}

						ItemStack result = wrapper.insertItem(slot, stack, simulate);

						if(simulate) {
							return result;
						}

						if(result.isEmpty() || result.getCount() != stack.getCount()) {
							target.getEntityData().setBoolean(NBT_HAS_NO_EQUIPMENT, false);

							equippable.onEquip(stack, target, inv);

							return ItemHandlerHelper.insertItem(wrapper, stack, false);
						}
					}
				}
			}
		}

		return stack;
	}

	/**
	 * Tries to unequip the first item found
	 * @param player
	 * @param target
	 * @return
	 */
	public static ItemStack unequipItem(@Nullable EntityPlayer player, Entity target, boolean simulate) {
		IEquipmentCapability cap = target.getCapability(CapabilityRegistry.CAPABILITY_EQUIPMENT, null);
		if(cap != null) {
			for(EnumEquipmentInventory type : EnumEquipmentInventory.VALUES) {
				IInventory inv = cap.getInventory(type);

				for(int i = 0; i < inv.getSizeInventory(); i++) {
					ItemStack stack = inv.getStackInSlot(i);

					if(!stack.isEmpty() && stack.getItem() instanceof IEquippable &&
							!((IEquippable) stack.getItem()).canUnequip(stack, player, target, cap.getInventory(((IEquippable) stack.getItem()).getEquipmentCategory(stack)))) {
						continue;
					}

					if(simulate) {
						return stack;
					}

					if(!stack.isEmpty()) {
						if(stack.getItem() instanceof IEquippable) {
							((IEquippable) stack.getItem()).onUnequip(stack, target, inv);
						}

						inv.setInventorySlotContents(i, ItemStack.EMPTY);
						return stack;
					}
				}
			}
		}

		return ItemStack.EMPTY;
	}

	/**
	 * Uneqips the item in the specified inventory and slot
	 * @param target
	 * @param type
	 * @param slot
	 * @return
	 */
	public static ItemStack unequipItem(@Nullable EntityPlayer player, Entity target, EnumEquipmentInventory type, int slot, boolean simulate) {
		IEquipmentCapability cap = target.getCapability(CapabilityRegistry.CAPABILITY_EQUIPMENT, null);
		if(cap != null) {
			IInventory inv = cap.getInventory(type);

			if(slot >= 0 && slot < inv.getSizeInventory()) {
				ItemStack stack = inv.getStackInSlot(slot);

				if(!stack.isEmpty() && stack.getItem() instanceof IEquippable &&
						!((IEquippable) stack.getItem()).canUnequip(stack, player, target, cap.getInventory(((IEquippable) stack.getItem()).getEquipmentCategory(stack)))) {
					return stack;
				}

				if(simulate) {
					return stack;
				}

				if(!stack.isEmpty() && stack.getItem() instanceof IEquippable) {
					((IEquippable) stack.getItem()).onUnequip(stack, target, inv);
				}

				inv.setInventorySlotContents(slot, ItemStack.EMPTY);

				return stack;
			}
		}

		return ItemStack.EMPTY;
	}

	/**
	 * Tries to unequip the first found item from the specified target
	 * @param player
	 * @param target
	 * @return True if successful
	 */
	public static boolean tryPlayerUnequip(EntityPlayer player, Entity target) {
		ItemStack unequipped = unequipItem(player, target, false);
		if(!unequipped.isEmpty()) {
			if(!player.inventory.addItemStackToInventory(unequipped)) {
				target.entityDropItem(unequipped, target.getEyeHeight());
			}

			return true;
		}
		return false;
	}
}

package thebetweenlands.common.capability.foodsickness;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

import net.minecraft.client.resources.I18n;
import net.minecraft.client.resources.IResourceManager;
import net.minecraft.client.resources.IResourceManagerReloadListener;
import net.minecraftforge.fml.common.FMLCommonHandler;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;

public enum FoodSickness {
	FINE(10 * 5),
	HALF(22 * 5),
	SICK(36 * 5);

	public final List<String> lines = new ArrayList<String>();
	public final int maxHatred;

	private FoodSickness(int maxHatred) {
		this.maxHatred = maxHatred;

		if(FMLCommonHandler.instance().getEffectiveSide() == Side.CLIENT) {
			this.updateLines();
		}
	}

	@SideOnly(Side.CLIENT)
	public void updateLines() {
		this.lines.clear();
		int index = 0;
		while (I18n.hasKey("chat.foodSickness." + name().toLowerCase() + "." + index)) {
			this.lines.add(I18n.format("chat.foodSickness." + name().toLowerCase() + "." + index));
			index++;
		}
	}

	@SideOnly(Side.CLIENT)
	public List<String> getLines() {
		return this.lines;
	}

	@SideOnly(Side.CLIENT)
	public String getRandomLine(Random rnd) {
		List<String> lines = this.getLines();
		if(lines.isEmpty()) {
			return "chat.foodSickness.nolines";
		}
		return lines.get(rnd.nextInt(lines.size()));
	}

	public static FoodSickness getSicknessForHatred(int hatred) {
		for (FoodSickness sickness : VALUES) {
			if (sickness.maxHatred > hatred) {
				return sickness;
			}
		}
		return VALUES[VALUES.length - 1];
	}

	public static final FoodSickness[] VALUES = values();

	public static class ResourceReloadListener implements IResourceManagerReloadListener {
		@Override
		public void onResourceManagerReload(IResourceManager resourceManager) {
			for(FoodSickness sickness : VALUES) {
				sickness.updateLines();
			}
		}
	}
}

package thebetweenlands.common.capability.foodsickness;

import java.util.Map;

import com.google.common.collect.Maps;

import net.minecraft.entity.Entity;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.Item;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.ResourceLocation;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.util.Constants;
import thebetweenlands.api.capability.IFoodSicknessCapability;
import thebetweenlands.api.capability.ISerializableCapability;
import thebetweenlands.common.capability.base.EntityCapability;
import thebetweenlands.common.handler.FoodSicknessHandler;
import thebetweenlands.common.lib.ModInfo;
import thebetweenlands.common.registries.CapabilityRegistry;

public class FoodSicknessEntityCapability extends EntityCapability<FoodSicknessEntityCapability, IFoodSicknessCapability, EntityPlayer> implements IFoodSicknessCapability, ISerializableCapability {
	@Override
	public ResourceLocation getID() {
		return new ResourceLocation(ModInfo.ID, "food_sickness");
	}

	@Override
	protected Capability<IFoodSicknessCapability> getCapability() {
		return CapabilityRegistry.CAPABILITY_FOOD_SICKNESS;
	}

	@Override
	protected Class<IFoodSicknessCapability> getCapabilityClass() {
		return IFoodSicknessCapability.class;
	}

	@Override
	protected FoodSicknessEntityCapability getDefaultCapabilityImplementation() {
		return new FoodSicknessEntityCapability();
	}

	@Override
	public boolean isApplicable(Entity entity) {
		return entity instanceof EntityPlayer;
	}

	@Override
	public boolean isPersistent(EntityPlayer oldPlayer, EntityPlayer newPlayer, boolean wasDead) {
		return true;
	}



	private Map<Item, Integer> hatredMap = Maps.newHashMap();
	private FoodSickness lastSickness = FoodSickness.FINE;

	@Override
	public FoodSickness getLastSickness() {
		return this.lastSickness;
	}

	@Override
	public void setLastSickness(FoodSickness sickness) {
		this.lastSickness = sickness;
	}

	@Override
	public FoodSickness getSickness(Item food) {
		return FoodSickness.getSicknessForHatred(this.getFoodHatred(food));
	}

	@Override
	public void decreaseHatredForAllExcept(Item food, int decrease) {
		if(decrease > 0) {
			Map<Item, Integer> newHatredMap = Maps.newHashMap();
			for (Item key : this.hatredMap.keySet()) {
				if (key != food) {
					newHatredMap.put(key, Math.max(this.hatredMap.get(key) - decrease, 0));
				}
			}
			if(!newHatredMap.isEmpty()) {
				this.hatredMap.putAll(newHatredMap);
				this.markDirty();
			}
		}
	}

	@Override
	public void increaseFoodHatred(Item food, int amount, int decreaseForOthers) {
		if (!FoodSicknessHandler.isFoodSicknessEnabled(this.getEntity().getEntityWorld()))
			return;
		int finalMaxHatred = FoodSickness.VALUES[Math.max(FoodSickness.VALUES.length - 1, 0)].maxHatred;
		if (this.hatredMap.containsKey(food)) {
			int currentAmount = this.hatredMap.get(food);
			this.hatredMap.put(food, Math.max(Math.min(currentAmount + amount, finalMaxHatred), 0));
		} else {
			this.hatredMap.put(food, Math.max(Math.min(amount, finalMaxHatred), 0));
		}
		this.decreaseHatredForAllExcept(food, decreaseForOthers);
		this.markDirty();
	}

	@Override
	public int getFoodHatred(Item food) {
		if (this.hatredMap.containsKey(food)) {
			return this.hatredMap.get(food);
		}
		return 0;
	}

	@Override
	public void writeToNBT(NBTTagCompound nbt) {
		NBTTagList list = new NBTTagList();
		for (Map.Entry<Item, Integer> entry : this.hatredMap.entrySet()) {
			NBTTagCompound listCompound = new NBTTagCompound();
			listCompound.setString("Food", entry.getKey().getRegistryName().toString());
			listCompound.setInteger("Level", entry.getValue());
			list.appendTag(listCompound);
		}
		nbt.setTag("HatredMap", list);
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		this.hatredMap = Maps.newHashMap();
		NBTTagList list = nbt.getTagList("HatredMap", Constants.NBT.TAG_COMPOUND);
		for (int i = 0; i < list.tagCount(); i++) {
			NBTTagCompound listCompound = list.getCompoundTagAt(i);
			Item food = Item.getByNameOrId(listCompound.getString("Food"));
			if(food != null) {
				int level = listCompound.getInteger("Level");
				this.hatredMap.put(food, level);
			}
		}
	}

	@Override
	public void writeTrackingDataToNBT(NBTTagCompound nbt) {
		this.writeToNBT(nbt);
	}

	@Override
	public void readTrackingDataFromNBT(NBTTagCompound nbt) {
		this.readFromNBT(nbt);
	}

	@Override
	public int getTrackingTime() {
		return 0;
	}
}

package thebetweenlands.common.capability.playermounts;

import java.util.ArrayList;
import java.util.List;

import net.minecraft.entity.Entity;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.ResourceLocation;
import net.minecraft.world.chunk.storage.AnvilChunkLoader;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.util.Constants;
import net.minecraftforge.event.entity.EntityMountEvent;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.gameevent.PlayerEvent.PlayerLoggedInEvent;
import thebetweenlands.api.capability.ISerializableCapability;
import thebetweenlands.api.entity.IEntityBL;
import thebetweenlands.common.capability.base.EntityCapability;
import thebetweenlands.common.lib.ModInfo;
import thebetweenlands.common.registries.CapabilityRegistry;

public class PlayerMountsEntityCapability extends EntityCapability<PlayerMountsEntityCapability, IPlayerMountsEntityCapability, EntityPlayer> implements IPlayerMountsEntityCapability, ISerializableCapability {
	@Override
	public ResourceLocation getID() {
		return new ResourceLocation(ModInfo.ID, "player_mounts");
	}

	@Override
	protected Capability<IPlayerMountsEntityCapability> getCapability() {
		return CapabilityRegistry.CAPABILITY_PLAYER_MOUNTS;
	}

	@Override
	protected Class<IPlayerMountsEntityCapability> getCapabilityClass() {
		return IPlayerMountsEntityCapability.class;
	}

	@Override
	protected PlayerMountsEntityCapability getDefaultCapabilityImplementation() {
		return new PlayerMountsEntityCapability();
	}

	@Override
	public boolean isApplicable(Entity entity) {
		return entity instanceof EntityPlayer;
	}



	private List<NBTTagCompound> queuedPassengers = new ArrayList<>();

	@Override
	public List<NBTTagCompound> getQueuedPassengers() {
		return this.queuedPassengers;
	}

	@Override
	public void writeToNBT(NBTTagCompound nbt) {
		EntityPlayer player = this.getEntity();

		if(player.isBeingRidden()) {
			NBTTagList passengers = new NBTTagList();

			for(Entity entity : player.getPassengers()) {
				if(entity instanceof IEntityBL) {
					NBTTagCompound passengerNbt = new NBTTagCompound();

					if(entity.writeToNBTAtomically(passengerNbt)) {
						passengers.appendTag(passengerNbt);
					}
				}
			}

			if(!passengers.isEmpty()) {
				nbt.setTag("PlayerPassengers", passengers);
			}
		}
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		this.queuedPassengers.clear();

		if(nbt.hasKey("PlayerPassengers", Constants.NBT.TAG_LIST)) {
			NBTTagList passengers = nbt.getTagList("PlayerPassengers", Constants.NBT.TAG_COMPOUND);

			for(int i = 0; i < passengers.tagCount(); ++i) {
				this.queuedPassengers.add(passengers.getCompoundTagAt(i));
			}
		}
	}

	/**
	 * Prevents player mounts from being removed before player is saved to NBT
	 */
	@SubscribeEvent
	public static void onMountEvent(EntityMountEvent event) {
		if(event.isDismounting()) {
			Entity mount = event.getEntityBeingMounted();
			Entity rider = event.getEntityMounting();

			if(mount instanceof EntityPlayerMP && rider instanceof IEntityBL) {
				EntityPlayerMP player = (EntityPlayerMP) mount;

				if(player.hasDisconnected()) {
					event.setCanceled(true);
				}
			}
		}
	}

	/**
	 * Spawns the player passengers from the NBT tags
	 */
	@SubscribeEvent
	public static void onPlayerJoin(PlayerLoggedInEvent event) {
		if(!event.player.world.isRemote) {
			IPlayerMountsEntityCapability cap = event.player.getCapability(CapabilityRegistry.CAPABILITY_PLAYER_MOUNTS, null);

			if(cap != null) {
				for(NBTTagCompound nbt : cap.getQueuedPassengers()) {
					Entity entity = AnvilChunkLoader.readWorldEntity(nbt, event.player.world, true);
					if(entity != null) {
						entity.startRiding(event.player, true);
					}
				}
			}
		}
	}
}

package thebetweenlands.common.handler;

import net.minecraft.enchantment.EnchantmentThorns;
import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.inventory.IInventory;
import net.minecraft.item.ItemStack;
import net.minecraft.util.DamageSource;
import net.minecraft.util.EntityDamageSource;
import net.minecraft.util.SoundCategory;
import net.minecraft.util.math.RayTraceResult;
import net.minecraft.util.math.Vec3d;
import net.minecraftforge.event.entity.living.LivingAttackEvent;
import net.minecraftforge.event.entity.living.LivingHurtEvent;
import net.minecraftforge.event.entity.living.LivingKnockBackEvent;
import net.minecraftforge.fml.common.eventhandler.EventPriority;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.network.NetworkRegistry.TargetPoint;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;
import thebetweenlands.api.capability.IEquipmentCapability;
import thebetweenlands.api.entity.IEntityBL;
import thebetweenlands.client.render.particle.BLParticles;
import thebetweenlands.client.render.particle.ParticleFactory.ParticleArgs;
import thebetweenlands.common.TheBetweenlands;
import thebetweenlands.common.capability.circlegem.CircleGemHelper;
import thebetweenlands.common.capability.equipment.EnumEquipmentInventory;
import thebetweenlands.common.item.armor.amphibious.AmphibiousArmorUpgrades;
import thebetweenlands.common.item.armor.amphibious.ItemAmphibiousArmor;
import thebetweenlands.common.network.clientbound.MessageDamageReductionParticle;
import thebetweenlands.common.network.clientbound.MessagePowerRingParticles;
import thebetweenlands.common.registries.CapabilityRegistry;
import thebetweenlands.common.registries.ItemRegistry;
import thebetweenlands.common.registries.SoundRegistry;

public class AttackDamageHandler {
	public static final float DAMAGE_REDUCTION = 0.3F;

	@SubscribeEvent
	public static void onEntityKnockback(LivingKnockBackEvent event) {
		EntityLivingBase attackedEntity = event.getEntityLiving();
		Entity attacker = event.getAttacker();

		if(attackedEntity instanceof IEntityBL && attacker instanceof EntityLivingBase && ((EntityLivingBase) attacker).getActiveHand() != null) {
			EntityLivingBase entityLiving = (EntityLivingBase) attacker;
			ItemStack heldItem = entityLiving.getHeldItem(entityLiving.getActiveHand());

			if (!heldItem.isEmpty() && OverworldItemHandler.isToolWeakened(heldItem)) {
				event.setStrength(event.getStrength() * 0.3F);
			}
		}
	}

	@SubscribeEvent(priority = EventPriority.LOW)
	public static void onEntityAttack(LivingAttackEvent event) {
		EntityLivingBase attackedEntity = event.getEntityLiving();
		DamageSource source = event.getSource();

		//Handle circle gem for blocking
		//For BL shields this is handled in ItemBLShield#onAttackBlocked
		if(canBlockDamageSource(attackedEntity, source)) {
			CircleGemHelper.handleAttack(source, attackedEntity, event.getAmount());
		}
	}

	private static boolean canBlockDamageSource(EntityLivingBase entity, DamageSource source) {
		if(!source.isUnblockable() && entity.isActiveItemStackBlocking() && (source instanceof EntityDamageSource == false || source.getTrueSource() != null)) {
			Vec3d location = source.getDamageLocation();

			if(location != null) {
				Vec3d look = entity.getLook(1.0F);
				Vec3d diff = location.subtractReverse(new Vec3d(entity.posX, entity.posY, entity.posZ)).normalize();
				diff = new Vec3d(diff.x, 0.0D, diff.z);

				if(diff.dotProduct(look) < 0.0D) {
					return true;
				}
			}
		}

		return false;
	}

	@SubscribeEvent
	public static void onEntityAttacked(LivingHurtEvent event) {
		EntityLivingBase attackedEntity = event.getEntityLiving();
		DamageSource source = event.getSource();
		float damage = event.getAmount();

		Entity entity = source.getTrueSource();
		if(attackedEntity instanceof IEntityBL && entity instanceof EntityLivingBase && ((EntityLivingBase) entity).getActiveHand() != null) {
			//BL mobs overworld item resistance
			EntityLivingBase attacker = (EntityLivingBase) entity;
			ItemStack heldItem = attacker.getHeldItem(attacker.getActiveHand());

			if (heldItem.isEmpty() || OverworldItemHandler.isToolWeakened(heldItem)) {
				//Cap damage of overly OP weapons
				damage = Math.min(damage, 40.0F);
			}

			if (!heldItem.isEmpty()) {
				if (OverworldItemHandler.isToolWeakened(heldItem)) {
					damage = damage * DAMAGE_REDUCTION;

					if(!attackedEntity.world.isRemote) {
						Vec3d center = attackedEntity.getPositionVector().add(0, attackedEntity.height / 2.0F, 0);

						Vec3d hitOffset = null;

						Entity immediateAttacker = source.getImmediateSource();

						if(immediateAttacker == null || attacker == immediateAttacker) {
							RayTraceResult result = attackedEntity.getEntityBoundingBox().calculateIntercept(attacker.getPositionEyes(1), attacker.getPositionEyes(1).add(attacker.getLookVec().scale(10)));
							if(result != null) {
								hitOffset = result.hitVec.subtract(center);
							}
						}
						if(immediateAttacker != null && hitOffset == null) {
							hitOffset = immediateAttacker.getPositionVector().add(0, immediateAttacker.height / 2.0F, 0).subtract(center);
						}
						if(hitOffset != null) {
							Vec3d offsetDirXZ = new Vec3d(hitOffset.x, 0, hitOffset.z).normalize();
							Vec3d offset = offsetDirXZ.scale(attackedEntity.width).add(0, hitOffset.y + attackedEntity.height / 2.0F, 0);

							attackedEntity.world.playSound(null, attackedEntity.posX, attackedEntity.posY + 0.5D, attackedEntity.posZ, SoundRegistry.DAMAGE_REDUCTION, SoundCategory.PLAYERS, 0.7F, 0.75F + attackedEntity.world.rand.nextFloat() * 0.3F);

							TheBetweenlands.networkWrapper.sendToAllAround(new MessageDamageReductionParticle(attackedEntity, offset, offsetDirXZ.scale(attackedEntity.width + 0.2F).normalize()), new TargetPoint(attackedEntity.dimension, attackedEntity.posX, attackedEntity.posY, attackedEntity.posZ, 32.0D));
						}
					}
				}
			}
		}

		damage = CircleGemHelper.handleAttack(source, attackedEntity, damage);

		if(entity instanceof EntityLivingBase) {
			IEquipmentCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_EQUIPMENT, null);
			if(cap != null) {
				IInventory inv = cap.getInventory(EnumEquipmentInventory.RING);
				int rings = 0;

				for(int i = 0; i < inv.getSizeInventory(); i++) {
					ItemStack stack = inv.getStackInSlot(i);
					if(!stack.isEmpty() && stack.getItem() == ItemRegistry.RING_OF_POWER && stack.getItemDamage() < stack.getMaxDamage()) {
						rings++;
					}
				}

				if(rings > 0) {
					TheBetweenlands.networkWrapper.sendToAllAround(new MessagePowerRingParticles(attackedEntity), new TargetPoint(attackedEntity.dimension, attackedEntity.posX, attackedEntity.posY, attackedEntity.posZ, 32.0D));
				}

				damage *= 1.0F + 0.5F * rings;
			}
		}

		int thornsCount = 0;

		for (ItemStack armor : attackedEntity.getArmorInventoryList()) {
			if (armor.getItem() instanceof ItemAmphibiousArmor) {
				if (((ItemAmphibiousArmor) armor.getItem()).getUpgradeCount(armor, AmphibiousArmorUpgrades.THORNS) >= 1) {
					thornsCount++;
				}
			}
		}

		if(entity != null && thornsCount > 0 && EnchantmentThorns.shouldHit(thornsCount, entity.world.rand)) {
			// Perhaps also damage armor like normal thorns would do? though thats usually really annoying
			entity.attackEntityFrom(DamageSource.causeThornsDamage(attackedEntity), thornsCount + entity.world.rand.nextInt(4));
		}

		event.setAmount(damage);
	}

	@SideOnly(Side.CLIENT)
	public static void spawnDamageReductionParticle(Entity entity, Vec3d offset, Vec3d dir) {
		BLParticles.DAMAGE_REDUCTION.spawn(entity.world, 0, 0, 0, ParticleArgs.get().withScale(2F).withData(entity, offset, dir));
	}

	@SideOnly(Side.CLIENT)
	public static void spawnPowerRingParticles(Entity entityHit) {
