package thebetweenlands.common.handler;

import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.item.Item;
import net.minecraft.item.ItemFood;
import net.minecraft.item.ItemStack;
import net.minecraft.util.EnumHand;
import net.minecraft.util.math.MathHelper;
import net.minecraft.util.text.TextComponentString;
import net.minecraft.world.World;
import net.minecraftforge.event.entity.living.LivingEntityUseItemEvent;
import net.minecraftforge.fml.common.eventhandler.EventPriority;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.gameevent.TickEvent.ClientTickEvent;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;
import thebetweenlands.api.capability.IDecayCapability;
import thebetweenlands.api.capability.IFoodSicknessCapability;
import thebetweenlands.api.item.IFoodSicknessItem;
import thebetweenlands.common.TheBetweenlands;
import thebetweenlands.common.capability.decay.DecayStats;
import thebetweenlands.common.capability.foodsickness.FoodSickness;
import thebetweenlands.common.config.BetweenlandsConfig;
import thebetweenlands.common.config.properties.ItemDecayFoodProperty.DecayFoodStats;
import thebetweenlands.common.network.clientbound.MessageShowFoodSicknessLine;
import thebetweenlands.common.registries.CapabilityRegistry;
import thebetweenlands.common.registries.GameruleRegistry;

public class FoodSicknessHandler {
	private FoodSicknessHandler() { }

	private static EnumHand lastHand = EnumHand.MAIN_HAND;
	private static ItemStack lastUsedItem = ItemStack.EMPTY;
	private static FoodSickness lastSickness = null;

	public static boolean isFoodSicknessEnabled(World world) {
		if(GameruleRegistry.getGameRuleBooleanValue(GameruleRegistry.BL_FOOD_SICKNESS)) {
			if(world.provider.getDimension() == BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId && BetweenlandsConfig.GENERAL.useFoodSicknessInBetweenlands) {
				return true;
			} else if(world.provider.getDimension() != BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId && BetweenlandsConfig.GENERAL.useFoodSicknessOutsideBetweenlands) {
				return true;
			}
		}

		return false;
	}

	@SideOnly(Side.CLIENT)
	@SubscribeEvent
	public static void onClientTick(ClientTickEvent event) {
		EntityPlayer player = TheBetweenlands.proxy.getClientPlayer();
		if(player != null) {
			if(!lastUsedItem.isEmpty() && (player.getHeldItem(lastHand).isEmpty() || !player.getHeldItem(lastHand).isItemEqual(lastUsedItem))) {
				lastUsedItem = ItemStack.EMPTY;
				lastSickness = null;
			}
		}
	}

	@SideOnly(Side.CLIENT)
	protected static void addSicknessMessage(EntityPlayer player, ItemStack item, FoodSickness sickness) {
		if(lastUsedItem.isEmpty() || !item.isItemEqual(lastUsedItem) || lastSickness == null || lastSickness != sickness) {
			player.sendStatusMessage(new TextComponentString(String.format(sickness.getRandomLine(player.getRNG()), item.getDisplayName())), true);
		}
		lastUsedItem = item;
		lastSickness = sickness;
	}

	@SubscribeEvent
	public static void onStartItemUse(LivingEntityUseItemEvent.Start event) {
		EntityPlayer player = event.getEntity() instanceof EntityPlayer ? (EntityPlayer) event.getEntity() : null;
		ItemStack itemStack = event.getItem();

		if (player != null && !itemStack.isEmpty() && FoodSicknessHandler.isFoodSicknessEnabled(event.getEntity().getEntityWorld()) && itemStack.getItem() instanceof IFoodSicknessItem && ((IFoodSicknessItem)itemStack.getItem()).canGetSickOf(player, itemStack)) {
			IFoodSicknessCapability cap = player.getCapability(CapabilityRegistry.CAPABILITY_FOOD_SICKNESS, null);
			if(cap != null) {
				Item item = itemStack.getItem();
				FoodSickness sickness = cap.getSickness(item);

				if(player.world.isRemote && sickness == FoodSickness.SICK) {
					addSicknessMessage(player, itemStack, sickness);
				}
			}
		}
	}

	@SubscribeEvent(priority = EventPriority.LOW)
	public static void onUseItemTick(LivingEntityUseItemEvent.Tick event) {
		//Check if item will be consumed this tick
		if(!event.getEntityLiving().getEntityWorld().isRemote && event.getDuration() <= 1) {
			EntityPlayer player = event.getEntity() instanceof EntityPlayer ? (EntityPlayer) event.getEntity() : null;
			ItemStack itemStack = event.getItem();

			if (player != null && !itemStack.isEmpty() && FoodSicknessHandler.isFoodSicknessEnabled(event.getEntity().getEntityWorld()) && itemStack.getItem() instanceof IFoodSicknessItem && ((IFoodSicknessItem)itemStack.getItem()).canGetSickOf(player, itemStack)) {
				IFoodSicknessCapability cap = player.getCapability(CapabilityRegistry.CAPABILITY_FOOD_SICKNESS, null);
				if(cap != null) {
					Item item = itemStack.getItem();

					FoodSickness lastSickness = cap.getLastSickness();

					int prevFoodHatred = cap.getFoodHatred(item);
					FoodSickness currentSickness = cap.getSickness(item);

					if(player.world.isRemote) {
						if(currentSickness != lastSickness && lastSickness == FoodSickness.SICK) {
							addSicknessMessage(player, itemStack, currentSickness);
						}
					}

					int sicknessIncrease = 5;

					if(currentSickness == FoodSickness.SICK) {
						if(item instanceof ItemFood) {
							int foodLevel = ((ItemFood)itemStack.getItem()).getHealAmount(itemStack);
							double foodLoss = 1.0D / 3.0D * 2.0;

							if(player.world.isRemote) {
								//Remove all gained food on client side and wait for sync
								player.getFoodStats().addStats(-Math.min(MathHelper.ceil(foodLevel * foodLoss), foodLevel), 0.0F);
							} else {
								int minFoodGain = player.world.rand.nextInt(4) == 0 ? 1 : 0;
								player.getFoodStats().addStats(-Math.min(MathHelper.ceil(foodLevel * foodLoss), Math.max(foodLevel - minFoodGain, 0)), 0.0F);
							}
						}

						DecayFoodStats decayFoodStats = OverworldItemHandler.getDecayFoodStats(itemStack);
						if(decayFoodStats != null) {
							IDecayCapability decayCap = player.getCapability(CapabilityRegistry.CAPABILITY_DECAY, null);
							if(decayCap != null) {
								int decayLevel = decayFoodStats.decay;
								DecayStats decayStats = decayCap.getDecayStats();
								double decayLoss = 1.0D / 3.0D * 2.0;

								if (player.world.isRemote) {
									//Remove all gained decay on client side and wait for sync
									decayStats.addStats(-Math.min(MathHelper.ceil(decayLevel * decayLoss), decayLevel), 0.0F);
								} else {
									int minDecayGain = player.world.rand.nextInt(4) == 0 ? 1 : 0;
									decayStats.addStats(-Math.min(MathHelper.ceil(decayLevel * decayLoss), Math.max(decayLevel - minDecayGain, 0)), 0.0F);
								}
							}
						}

						if(!player.world.isRemote) {
							cap.increaseFoodHatred(item, sicknessIncrease, 0);
						}
					} else {
						if(!player.world.isRemote) {
							cap.increaseFoodHatred(item, sicknessIncrease, prevFoodHatred <= 2 * 5 ? 4 : 3);
						}
					}

					FoodSickness newSickness = cap.getSickness(item);

					if(!player.world.isRemote && player instanceof EntityPlayerMP) {
						if(newSickness != lastSickness) {
							TheBetweenlands.networkWrapper.sendTo(new MessageShowFoodSicknessLine(itemStack, newSickness), (EntityPlayerMP) player);
						}
					}

					cap.setLastSickness(newSickness);
				}
			}
		}
	}
}

package thebetweenlands.common.handler;

import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.item.EntityItem;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.inventory.IInventory;
import net.minecraft.item.ItemStack;
import net.minecraft.util.EnumHand;
import net.minecraft.util.ITickable;
import net.minecraft.util.text.TextComponentTranslation;
import net.minecraftforge.event.entity.living.LivingDropsEvent;
import net.minecraftforge.event.entity.living.LivingEvent;
import net.minecraftforge.event.entity.player.PlayerInteractEvent;
import net.minecraftforge.event.entity.player.PlayerInteractEvent.EntityInteract;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import thebetweenlands.api.capability.IEquipmentCapability;
import thebetweenlands.api.item.IEquippable;
import thebetweenlands.common.TheBetweenlands;
import thebetweenlands.common.capability.equipment.EnumEquipmentInventory;
import thebetweenlands.common.capability.equipment.EquipmentHelper;
import thebetweenlands.common.network.serverbound.MessageEquipItem;
import thebetweenlands.common.registries.CapabilityRegistry;

public class ItemEquipmentHandler {
	private ItemEquipmentHandler() { }

	@SubscribeEvent
	public static void onLivingUpdated(LivingEvent.LivingUpdateEvent event) {
		Entity entity = event.getEntity();

		if(!entity.getEntityData().getBoolean(EquipmentHelper.NBT_HAS_NO_EQUIPMENT)) {
			IEquipmentCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_EQUIPMENT, null);

			if (cap != null) {
				for (EnumEquipmentInventory invType : EnumEquipmentInventory.VALUES) {
					IInventory inventory = cap.getInventory(invType);

					if (inventory instanceof ITickable) {
						((ITickable) inventory).update();
					}
				}

				if((entity.ticksExisted + entity.getEntityId()) % 100 == 0) {
					boolean hasEquipment = false;

					loop: for(EnumEquipmentInventory invType : EnumEquipmentInventory.VALUES) {
						IInventory inventory = cap.getInventory(invType);

						for(int i = 0; i < inventory.getSizeInventory(); i++) {
							if(!inventory.getStackInSlot(i).isEmpty()) {
								hasEquipment = true;
								break loop;
							}
						}
					}

					//Put equipment ticking back to sleep until items are added again
					if(!hasEquipment) {
						entity.getEntityData().setBoolean(EquipmentHelper.NBT_HAS_NO_EQUIPMENT, true);
					}
				}
			} else {
				entity.getEntityData().setBoolean(EquipmentHelper.NBT_HAS_NO_EQUIPMENT, true);
			}
		}
	}

	@SubscribeEvent
	public static void onEntityInteract(EntityInteract event) {
		EntityPlayer player = event.getEntityPlayer();
		Entity target = event.getTarget();

		if(player != null && target != null && target instanceof EntityPlayer == false) {
			ItemStack heldItem = event.getItemStack();

			if(!player.isSneaking() && !heldItem.isEmpty()) {
				if(heldItem.getItem() instanceof IEquippable) {
					IEquippable equippable = (IEquippable) heldItem.getItem();

					if(equippable.canEquipOnRightClick(heldItem, player, target)) {
						ItemStack result = EquipmentHelper.equipItem(player, target, heldItem, false);

						if(result.isEmpty() || result.getCount() != heldItem.getCount()) {
							if(!player.capabilities.isCreativeMode) {
								player.setHeldItem(event.getHand(), result);
							}

							player.swingArm(event.getHand());
						}
					}
				}
			} else if(player.isSneaking() && heldItem.isEmpty()) {
				if(EquipmentHelper.tryPlayerUnequip(player, target)) {
					player.swingArm(EnumHand.MAIN_HAND);
					event.setCanceled(true);
				}
			}
		}
	}

	@SubscribeEvent
	public static void onItemUse(PlayerInteractEvent event) {
		EntityPlayer player = event.getEntityPlayer();
		if(event instanceof PlayerInteractEvent.RightClickBlock) {
			tryEquip(player, event.getHand(), false);
		} else if(event instanceof PlayerInteractEvent.RightClickEmpty) {
			if(!tryEquip(player, EnumHand.MAIN_HAND, true)) {
				tryEquip(player, EnumHand.OFF_HAND, true);
			}
		}
	}

	private static boolean tryEquip(EntityPlayer player, EnumHand hand, boolean packet) {
		ItemStack heldItem = player.getHeldItem(hand);

		if(player != null && !heldItem.isEmpty() && heldItem.getItem() instanceof IEquippable) {
			IEquippable equippable = (IEquippable) heldItem.getItem();

			if(equippable.canEquipOnRightClick(heldItem, player, player)) {
				if(packet) {
					if(player.world.isRemote) {
						ItemStack result = EquipmentHelper.equipItem(player, player, heldItem, true);

						if(result.isEmpty() || result.getCount() != heldItem.getCount()) {
							if(hand == EnumHand.OFF_HAND) {
								TheBetweenlands.networkWrapper.sendToServer(new MessageEquipItem(-1, player));

								player.swingArm(hand);

								return true;
							} else {
								int slot = player.inventory.getSlotFor(heldItem);
								if(slot >= 0) {
									TheBetweenlands.networkWrapper.sendToServer(new MessageEquipItem(slot, player));

									player.swingArm(hand);

									return true;
								}
							}
						}
					}
				} else {
					if(player.world.isRemote) {
						ItemStack result = EquipmentHelper.equipItem(player, player, heldItem, true);

						if(result.isEmpty() || result.getCount() != heldItem.getCount()) {
							player.swingArm(hand);
							return true;
						}
					} else {
						ItemStack result = EquipmentHelper.equipItem(player, player, heldItem, false);

						if(result.isEmpty() || result.getCount() != heldItem.getCount()) {
							if(!player.capabilities.isCreativeMode) {
								player.setHeldItem(hand, result);
							}

							player.swingArm(hand);

							player.sendStatusMessage(new TextComponentTranslation("chat.equipment.equipped", new TextComponentTranslation(heldItem.getTranslationKey() + ".name")), true);

							return true;
						}
					}
				}
			}
		}

		return false;
	}

	@SubscribeEvent
	public static void onDeathDrops(LivingDropsEvent event) {
		EntityLivingBase entity = event.getEntityLiving();

		if(entity != null && !entity.world.isRemote && !entity.world.getGameRules().getBoolean("keepInventory")) {
			IEquipmentCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_EQUIPMENT, null);
			if(cap != null) {
				for(EnumEquipmentInventory type : EnumEquipmentInventory.VALUES) {
					IInventory inv = cap.getInventory(type);

					for(int i = 0; i < inv.getSizeInventory(); i++) {
						ItemStack stack = inv.getStackInSlot(i);

						if(!stack.isEmpty()) {
							if(stack.getItem() instanceof IEquippable) {
								IEquippable equippable = (IEquippable) stack.getItem();
								equippable.onUnequip(stack, entity, inv);
								if(!equippable.canDrop(stack, entity, inv)) {
									continue;
								}
							}

							EntityItem equipmentDrop = new EntityItem(entity.world, entity.posX, entity.posY + entity.getEyeHeight(), entity.posZ, stack.copy());
							equipmentDrop.setDefaultPickupDelay();
							event.getDrops().add(equipmentDrop);
						}
					}

					inv.clear();
				}
			}
		}
	}
}

package thebetweenlands.common.handler;

import java.util.Collections;

import javax.annotation.Nullable;

import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.Entity;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.network.play.server.SPacketSpawnPosition;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.BlockPos.MutableBlockPos;
import net.minecraft.world.World;
import net.minecraft.world.WorldServer;
import net.minecraft.world.chunk.Chunk;
import net.minecraftforge.common.util.Constants;
import net.minecraftforge.event.entity.living.LivingDeathEvent;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.gameevent.PlayerEvent.PlayerRespawnEvent;
import thebetweenlands.api.entity.spawning.IWeightProvider;
import thebetweenlands.common.config.BetweenlandsConfig;
import thebetweenlands.common.world.teleporter.TeleporterBetweenlands;
import thebetweenlands.common.world.teleporter.TeleporterHandler;
import thebetweenlands.util.WeightedList;

public class PlayerRespawnHandler {
	public static final String RESPAWN_IN_BL_NBT = "thebetweenlands.respawn_in_bl";

	@SubscribeEvent
	public static void onPlayerDeath(LivingDeathEvent event) {
		if(event.getEntityLiving() instanceof EntityPlayer) {
			EntityPlayer player = (EntityPlayer) event.getEntityLiving();

			NBTTagCompound dataNbt = player.getEntityData();
			NBTTagCompound persistentNbt = dataNbt.getCompoundTag(EntityPlayer.PERSISTED_NBT_TAG);

			BlockPos spawnPos = player.getBedLocation(player.dimension);

			BlockPos adjustedSpawnPos = spawnPos == null ? null : EntityPlayer.getBedSpawnLocation(player.world, spawnPos, player.isSpawnForced(player.dimension));

			boolean respawnInBL = BetweenlandsConfig.WORLD_AND_DIMENSION.startInBetweenlands && (!player.world.provider.canRespawnHere() || adjustedSpawnPos == null);

			persistentNbt.setBoolean(RESPAWN_IN_BL_NBT, respawnInBL);

			dataNbt.setTag(EntityPlayer.PERSISTED_NBT_TAG, persistentNbt);
		}
	}


	@SubscribeEvent
	public static void onRespawn(PlayerRespawnEvent event) {
		if(!event.player.world.isRemote) {
			BlockPos spawnPos = event.player.getBedLocation(event.player.dimension);

			BlockPos adjustedSpawnPos = spawnPos == null ? null : EntityPlayer.getBedSpawnLocation(event.player.world, spawnPos, event.player.isSpawnForced(event.player.dimension));

			NBTTagCompound dataNbt = event.player.getEntityData();
			NBTTagCompound persistentNbt = dataNbt.getCompoundTag(EntityPlayer.PERSISTED_NBT_TAG);

			boolean shouldTeleportToBL = (BetweenlandsConfig.WORLD_AND_DIMENSION.startInBetweenlands && event.isEndConquered()) || persistentNbt.getBoolean(RESPAWN_IN_BL_NBT);

			if(shouldTeleportToBL && event.player.world instanceof WorldServer) {
				WorldServer blWorld = ((WorldServer) event.player.world).getMinecraftServer().getWorld(BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId);

				TeleporterHandler.transferToDim(event.player, blWorld, false, false);

				spawnPos = event.player.getBedLocation(event.player.dimension);

				adjustedSpawnPos = spawnPos == null ? null : EntityPlayer.getBedSpawnLocation(event.player.world, spawnPos, event.player.isSpawnForced(event.player.dimension));

				if(adjustedSpawnPos != null) {
					event.player.setPosition(adjustedSpawnPos.getX() + 0.5D, adjustedSpawnPos.getY(), adjustedSpawnPos.getZ() + 0.5D);

					if(event.player instanceof EntityPlayerMP) {
						EntityPlayerMP playerMP = (EntityPlayerMP) event.player;

						playerMP.connection.setPlayerLocation(playerMP.posX, playerMP.posY, playerMP.posZ, playerMP.rotationYaw, playerMP.rotationPitch);
						playerMP.connection.sendPacket(new SPacketSpawnPosition(adjustedSpawnPos));
					}
				}
			}

			if(shouldTeleportToBL || event.player.dimension == BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId) {
				boolean newRespawn = false;
				if(adjustedSpawnPos == null) {
					newRespawn = true;
				} else {
					IBlockState stateDown = event.player.world.getBlockState(adjustedSpawnPos.down());
					boolean isValidSpawnBlock = stateDown.getMaterial().blocksMovement() && !stateDown.getBlock().isLeaves(stateDown, event.player.world, adjustedSpawnPos.down()) && !stateDown.getBlock().isFoliage(event.player.world, adjustedSpawnPos.down());
					if(!isValidSpawnBlock) {
						newRespawn = true;
					}
				}

				if(newRespawn) {
					if(persistentNbt.hasKey(TeleporterBetweenlands.LAST_PORTAL_POS_NBT, Constants.NBT.TAG_LONG)) {
						BlockPos lastPortal = BlockPos.fromLong(persistentNbt.getLong(TeleporterBetweenlands.LAST_PORTAL_POS_NBT));

						respawnNearPos(event.player, lastPortal);
					}
				}
			}
		}
	}

	public static void respawnNearPos(Entity entity, BlockPos pos) {
		BlockPos newSpawn = getRespawnPointNearPos(entity.world, pos, 64);

		entity.setLocationAndAngles(newSpawn.getX() + 0.5D, newSpawn.getY(), newSpawn.getZ() + 0.5D, entity.rotationYaw, entity.rotationPitch);

		while (!entity.world.getCollisionBoxes(entity, entity.getEntityBoundingBox()).isEmpty() && entity.posY < 256.0D) {
			entity.setPosition(entity.posX, entity.posY + 1.0D, entity.posZ);
		}

		newSpawn = new BlockPos(entity);

		if(entity instanceof EntityPlayer) {
			((EntityPlayer)entity).setSpawnPoint(newSpawn, true);
		}

		if(entity instanceof EntityPlayerMP) {
			EntityPlayerMP playerMP = (EntityPlayerMP) entity;

			playerMP.connection.setPlayerLocation(playerMP.posX, playerMP.posY, playerMP.posZ, playerMP.rotationYaw, playerMP.rotationPitch);
			playerMP.connection.sendPacket(new SPacketSpawnPosition(newSpawn));
		}
	}

	public static BlockPos getRespawnPointNearPos(World world, BlockPos pos, int fuzz) {
		BlockPos result = getSpawnPointNearPos(world, pos, fuzz, true, 16, 3);
		if(result == null) {
			int spawnFuzz = fuzz;
			int spawnFuzzHalf = spawnFuzz / 2;
			result = world.getTopSolidOrLiquidBlock(pos.add(world.rand.nextInt(spawnFuzz) - spawnFuzzHalf, 0, world.rand.nextInt(spawnFuzz) - spawnFuzzHalf));
		}
		return result;
	}

	@Nullable
	public static BlockPos getSpawnPointNearPos(World world, BlockPos pos, int fuzz, boolean surface, int yRange, int xzSkip) {
		xzSkip = Math.max(xzSkip, 1);

		int spawnFuzz = fuzz;
		int spawnFuzzHalf = spawnFuzz / 2;

		class WeightedPos implements IWeightProvider {
			final BlockPos pos;
			short weight;

			WeightedPos(BlockPos pos) {
				this.pos = pos;
			}

			@Override
			public short getWeight() {
				return this.weight;
			}
		}

		short maxWeight = 0;

		WeightedList<WeightedPos> spawnCandidates = new WeightedList<>();

		MutableBlockPos checkPos = new MutableBlockPos();

		for(int xo = -spawnFuzzHalf; xo <= spawnFuzzHalf; xo += 1 + world.rand.nextInt(xzSkip)) {
			for(int zo = -spawnFuzzHalf; zo <= spawnFuzzHalf; zo += 1 + world.rand.nextInt(xzSkip)) {
				checkPos.setPos(pos.getX() + xo, 0, pos.getZ() + zo);

				Chunk chunk = world.getChunk(checkPos);

				for(int yo = yRange; surface || yo >= -yRange; yo--) {
					if(surface) {
						checkPos.setPos(checkPos.getX(), chunk.getHeight(checkPos), checkPos.getZ());
					} else {
						checkPos.setPos(checkPos.getX(), pos.getY() + yo, checkPos.getZ());
					}

					if(Math.abs(checkPos.getY() - pos.getY()) <= yRange && EntityPlayer.getBedSpawnLocation(world, checkPos, true) != null) {
						checkPos.setY(checkPos.getY() - 1);

						IBlockState stateDown = chunk.getBlockState(checkPos);
						if(stateDown.getMaterial().blocksMovement() && !stateDown.getBlock().isLeaves(stateDown, world, checkPos) && !stateDown.getBlock().isFoliage(world, checkPos)) {
							BlockPos newPos = checkPos.up();
							WeightedPos p = new WeightedPos(newPos);
							p.weight = (short)Math.abs(newPos.getY() - pos.getY());
							maxWeight = (short)Math.max(maxWeight, p.weight);
							spawnCandidates.add(p);
						}
					}

					if(surface) {
						break;
					}
				}
			}
		}

		if(!spawnCandidates.isEmpty()) {
			Collections.shuffle(spawnCandidates, world.rand);

			for(WeightedPos p : spawnCandidates) {
				p.weight = (short) (maxWeight - p.weight);
				p.weight = (short) Math.pow(p.weight, 1.5D);
			}

			spawnCandidates.recalculateWeight();

			return spawnCandidates.getRandomItem(world.rand).pos;
		}

		return null;
	}
}

package thebetweenlands.common.inventory;

import javax.annotation.Nonnull;
import javax.annotation.Nullable;

import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.inventory.IInventory;
import net.minecraft.inventory.ItemStackHelper;
import net.minecraft.item.ItemStack;
import net.minecraft.util.ITickable;
import net.minecraft.util.NonNullList;
import net.minecraft.util.text.ITextComponent;
import net.minecraft.util.text.TextComponentString;
import net.minecraft.util.text.TextComponentTranslation;
import net.minecraftforge.common.MinecraftForge;
import thebetweenlands.api.event.EquipmentChangedEvent;
import thebetweenlands.api.item.IEquippable;
import thebetweenlands.common.capability.equipment.EquipmentEntityCapability;

public class InventoryEquipment implements IInventory, ITickable {
    protected final NonNullList<ItemStack> inventory;
    protected final NonNullList<ItemStack> prevTickStacks;
    protected final EquipmentEntityCapability capability;
    private int lastChangeCheck = 0;

    public InventoryEquipment(EquipmentEntityCapability capability, NonNullList<ItemStack> inventory) {
        this.capability = capability;
        this.inventory = inventory;
        this.prevTickStacks = NonNullList.withSize(inventory.size(), ItemStack.EMPTY);

        for (int i = 0; i < this.inventory.size(); i++) {
            ItemStack stack = this.inventory.get(i);
            if (!stack.isEmpty())
                this.prevTickStacks.set(i, stack.isEmpty() ? ItemStack.EMPTY : stack.copy());
        }
    }

    @Override
    public String getName() {
        return "container.bl.equipment";
    }

    @Override
    public boolean hasCustomName() {
        return false;
    }

    @Override
    public ITextComponent getDisplayName() {
        return (ITextComponent) (this.hasCustomName() ? new TextComponentString(this.getName()) : new TextComponentTranslation(this.getName(), new Object[0]));
    }

    @Override
    @Nullable
    public ItemStack removeStackFromSlot(int index) {
        ItemStack stack = ItemStack.EMPTY;
        if (index < this.getSizeInventory()) {
            stack = ItemStackHelper.getAndRemove(inventory, index);
            this.markDirty();
        }
        return stack;
    }

    @Override
    @Nullable
    public ItemStack decrStackSize(int index, int count) {
        ItemStack stack = ItemStack.EMPTY;
        if (index < this.getSizeInventory()) {
            stack = ItemStackHelper.getAndSplit(inventory, index, count);
            this.markDirty();
        }
        return stack;
    }

    @Override
    public void setInventorySlotContents(int index, @Nonnull ItemStack stack) {
        if (index < this.getSizeInventory()) {
            this.inventory.set(index, stack);
            this.markDirty();
        }
    }

    @Override
    public int getInventoryStackLimit() {
        return 64;
    }

    @Override
    public void markDirty() {
        this.capability.markDirty();
        MinecraftForge.EVENT_BUS.post(new EquipmentChangedEvent(this.capability.getEntity(), this.capability));
    }

    @Override
    public boolean isUsableByPlayer(EntityPlayer player) {
        return false;
    }


    @Override
    public void openInventory(EntityPlayer player) {

    }

    @Override
    public void closeInventory(EntityPlayer player) {

    }

    @Override
    public boolean isItemValidForSlot(int index, ItemStack stack) {
        if (index < this.getSizeInventory()) {
            return true;
        } else {
            return false;
        }
    }

    @Override
    public int getField(int id) {
        return 0;
    }

    @Override
    public void setField(int id, int value) {

    }

    @Override
    public int getFieldCount() {
        return 0;
    }

    @Override
    public void clear() {
        for (int i = 0; i < this.inventory.size(); ++i) {
            this.inventory.set(i, ItemStack.EMPTY);
        }
        this.markDirty();
    }

    @Override
    public int getSizeInventory() {
        return this.inventory.size();
    }

    @Override
    public boolean isEmpty() {
        return inventory.size() <= 0;
    }

    @Override
    @Nullable
    public ItemStack getStackInSlot(int index) {
        return index >= this.getSizeInventory() ? ItemStack.EMPTY : this.inventory.get(index);
    }

    @Override
    public void update() {
        for (int i = 0; i < this.inventory.size(); i++) {
            ItemStack stack = this.inventory.get(i);

            if (!stack.isEmpty() && stack.getItem() instanceof IEquippable) {
                ((IEquippable) stack.getItem()).onEquipmentTick(stack, this.capability.getEntity(), this);
            }
        }

        if(this.lastChangeCheck++ > 10) {
        	this.detectChangesAndMarkDirty();
        	this.lastChangeCheck = 0;
        }
    }

    protected void detectChangesAndMarkDirty() {
        for (int i = 0; i < this.inventory.size(); ++i) {
            ItemStack stack = this.inventory.get(i);
            ItemStack prevStack = this.prevTickStacks.get(i);

            if (!ItemStack.areItemStacksEqual(prevStack, stack)) {
                this.prevTickStacks.set(i, stack.isEmpty() ? ItemStack.EMPTY : stack.copy());
                this.markDirty();
            }
        }
    }
}

